  bool refused=false;try{restarted.declareModel("small",folder.getChildFile("small.gguf"));}catch(...){refused=true;}check(refused,"Manual GGUF declaration checks the official hash");
  {juce::FileOutputStream image(folder.getChildFile("family-settings.png"));panel.update(available);juce::PNGImageFormat().writeImageToStream(panel.createComponentSnapshot(panel.getLocalBounds()),image);}
  auto sf=folder.getChildFile("non-gm.sf2");juce::MemoryBlock bytes;auto piano=optionalRoot().getChildFile("player-assets/piano.sf2");check(piano.loadFileAsData(bytes),"Read included piano as independent SF2 fixture");
