  check(after["part"]["soundfont"]["path"].toString()==sf.getFullPathName()&&after["part"]["label"]==before["part"]["label"]&&after["start_time_s"]==before["start_time_s"]&&after["end_time_s"]==before["end_time_s"]&&after["pitch_midi"]==before["pitch_midi"]&&after["velocity_midi"]==before["velocity_midi"],"Assigning a custom bank preserves voice name, pitch, timing and velocity");
  selectPart(256);customInstrument(256);check(!Form::activeForms.empty(),"Voice instrument opens the bank and preset chooser");auto* instrument=*Form::activeForms.rbegin();check(instrument->comboFields.count("soundfont_bank")&&instrument->comboFields.count("preset")&&int(instrument->state()["part"])==256,"Instrument chooser targets the selected voice");instrument->comboFields["soundfont_bank"]->setSelectedId(2,juce::sendNotificationSync);check(int(instrument->state()["soundfont"]["bank"])==3&&int(instrument->state()["soundfont"]["preset"])==7,"Bank selection exposes the real non-GM preset");{juce::FileOutputStream image(folder.getChildFile("instrument-settings.png"));juce::PNGImageFormat().writeImageToStream(instrument->createComponentSnapshot(instrument->getLocalBounds()),image);}instrument->close();
  edit(object({{"kind","undo"}}));check(!items(result["editing"]["notes"])[0]["part"].hasProperty("soundfont"),"Undo restores the previous sound bank");edit(object({{"kind","redo"}}));check(items(result["editing"]["notes"])[0]["part"]["soundfont"]["bank"]==var(3),"Redo restores the precise non-GM preset");
